import{_ as e}from"./chunks/100.Bym1HttY.js";import{_ as o,o as r,c as a,ak as i}from"./chunks/framework.Ba6sv-31.js";const s="/projects/AiBlockSensor/en/latest/assets/1.tuzzcRuO.webp",n="/projects/AiBlockSensor/en/latest/assets/2.C0ciAv1z.webp",l="/projects/AiBlockSensor/en/latest/assets/3.Dl8K5mf6.webp",c="/projects/AiBlockSensor/en/latest/assets/4.1zARL_-A.webp",d="/projects/AiBlockSensor/en/latest/assets/5.CNpu-FA6.webp",x=JSON.parse('{"title":"13. Soil Moisture Sensor","description":"","frontmatter":{},"headers":[],"relativePath":"docs/13. Soil Moisture Sensor.md","filePath":"docs/13. Soil Moisture Sensor.md"}'),h={name:"docs/13. Soil Moisture Sensor.md"};function m(p,t,g,u,_,f){return r(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="_13-soil-moisture-sensor" tabindex="-1">13. Soil Moisture Sensor <a class="header-anchor" href="#_13-soil-moisture-sensor" aria-label="Permalink to &quot;13. Soil Moisture Sensor&quot;">​</a></h1><h2 id="_13-1-introduction" tabindex="-1">13.1 Introduction <a class="header-anchor" href="#_13-1-introduction" aria-label="Permalink to &quot;13.1 Introduction&quot;">​</a></h2><p>Designed to assess soil moisture conditions, the soil moisture sensor translates moisture levels into continuous analog signal outputs. Combining this sensor with a miniature water pump and irrigation tubing creates a self-tending plant care system that automatically hydrates dry soil.</p><img loading="lazy" height="348" width="685" src="'+s+'" class="common_img" style="width:300px;"><h2 id="_13-2-technical-specifications" tabindex="-1">13.2 Technical Specifications <a class="header-anchor" href="#_13-2-technical-specifications" aria-label="Permalink to &quot;13.2 Technical Specifications&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Parameter</th><th style="text-align:center;">Description</th></tr></thead><tbody><tr><td style="text-align:center;">Operating voltage</td><td style="text-align:center;">5 V</td></tr><tr><td style="text-align:center;">Surface finish</td><td style="text-align:center;">ENIG finish</td></tr><tr><td style="text-align:center;">Connector model</td><td style="text-align:center;">5264-4AW</td></tr><tr><td style="text-align:center;">Mounting compatibility</td><td style="text-align:center;">LEGO-compatible hole spacing</td></tr><tr><td style="text-align:center;">Dimensions</td><td style="text-align:center;">35.5 × 11.7 × 7.7 mm</td></tr></tbody></table><h2 id="_13-3-hands-on-project" tabindex="-1">13.3 Hands-On Project <a class="header-anchor" href="#_13-3-hands-on-project" aria-label="Permalink to &quot;13.3 Hands-On Project&quot;">​</a></h2><h3 id="_13-3-1-project-introduction" tabindex="-1">13.3.1 Project Introduction <a class="header-anchor" href="#_13-3-1-project-introduction" aria-label="Permalink to &quot;13.3.1 Project Introduction&quot;">​</a></h3><p>This project reads analog values from the soil moisture sensor and prints the results to the serial monitor. Inserting the probe into dry or moist soil causes the readings to change, demonstrating how the sensor measures soil moisture.</p><h3 id="_13-3-2-hardware-wiring" tabindex="-1">13.3.2 Hardware Wiring <a class="header-anchor" href="#_13-3-2-hardware-wiring" aria-label="Permalink to &quot;13.3.2 Hardware Wiring&quot;">​</a></h3><ul><li>Connect the soil moisture sensor to port <strong>A</strong> of the controller using a 4-pin module cable.</li></ul><img loading="lazy" height="403" width="1040" src="'+n+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>This sensor supports connection to any port among A, B, C, or D on the controller. Ensure that the port selected in the program matches the physical wiring.</strong></p></div><h3 id="_13-3-3-adding-extensions" tabindex="-1">13.3.3 Adding Extensions <a class="header-anchor" href="#_13-3-3-adding-extensions" aria-label="Permalink to &quot;13.3.3 Adding Extensions&quot;">​</a></h3><ul><li>Select <strong>Soil sensor</strong> under the <strong>Input Module</strong> category.</li></ul><img loading="lazy" height="1040" width="1920" src="'+l+'" class="common_img" style="width:800px;"><h3 id="_13-3-4-complete-program-and-analysis" tabindex="-1">13.3.4 Complete Program and Analysis <a class="header-anchor" href="#_13-3-4-complete-program-and-analysis" aria-label="Permalink to &quot;13.3.4 Complete Program and Analysis&quot;">​</a></h3><ol><li><p>Inside the infinite loop of the main program, continuously sample the soil moisture analog value from the soil moisture sensor on port A.</p></li><li><p>Print the soil moisture reading over the serial port.</p></li><li><p>Add a 0.5-second wait to moderate the serial refresh rate, facilitating stable data observation.</p></li></ol><img loading="lazy" height="231" width="711" src="'+c+'" class="common_img" style="width:500px;"><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>The source files are available for download under <a href="https://drive.google.com/drive/folders/1fLfLXEVjSMZdojOq7C44xJqZIBm4MDem?usp=sharing" target="_blank" rel="noreferrer">Program Files/ 13 Soil Sensor.sb3</a>.</strong></p></div><h3 id="_13-3-5-program-upload" tabindex="-1">13.3.5 Program Upload <a class="header-anchor" href="#_13-3-5-program-upload" aria-label="Permalink to &quot;13.3.5 Program Upload&quot;">​</a></h3><ul><li>Click <strong>Connect device</strong>, select the serial port, then click the upload button. Wait for the upload success notification to complete the program transfer.</li></ul><img loading="lazy" height="360" width="640" src="'+e+'" class="common_img" style="width:800px;"><h3 id="_13-3-6-program-outcome" tabindex="-1">13.3.6 Program Outcome <a class="header-anchor" href="#_13-3-6-program-outcome" aria-label="Permalink to &quot;13.3.6 Program Outcome&quot;">​</a></h3><p>Once the program upload is complete, open the serial monitor in the lower-right corner of the programming software. When the probe is placed in dry soil, the serial monitor reports a low moisture value. Inserting the probe into moist soil drives the reading upward across a range between 0 and 100.</p><img loading="lazy" height="955" width="1525" src="'+d+'" class="common_img" style="width:800px;">',26)])])}const S=o(h,[["render",m]]);export{x as __pageData,S as default};
